SELECT case_id, sequence_no AS depth, node_type, node_id, parent_node_id, source_table, source_column, snapshot_id, CAST(NULL AS STRING) target_table, CAST(NULL AS STRING) target_column, 'VALUE_LINEAGE' lineage_source FROM {{PUBLIC}}.calculation_trace UNION ALL SELECT case_id, 100, 'TECHNICAL_OBJECT', CONCAT(source_table,':',COALESCE(source_column,'*')), NULL, source_table, source_column, NULL, target_table, target_column, lineage_source FROM {{PUBLIC}}.technical_lineage_curated
